    "input": "25\n-35 -35\n20 26\n-17 -13\n10 11\n-22 -21\n-41 -41\n-25 -20\n21 24\n26 31\n18 18\n-38 -32\n40 45\n-23 -18\n-8 -2\n-39 -39\n23 26\n-40 -34\n50 54\n-37 -35\n6 11\n49 53\n-35 -33\n17 17\n48 51\n46 50\n",
    "output": "-41 -41\n-40 -32\n-25 -18\n-17 -13\n-8 -2\n6 11\n17 17\n18 18\n20 31\n40 45\n46 54",
